def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        # Find all columns in this row where value equals x
        cols = [j for j, val in enumerate(row) if val == x]
        # Sort columns in descending order
        cols.sort(reverse=True)
        for col in cols:
            result.append((i, col))
    return result

