def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            base = ord('a') if char.islower() else ord('A')
            # Shift down by 4 (2 * 2)
            shifted = (ord(char) - base + 4) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)
